group by outbound_status

select outbound_type as type, CASE outbound_type WHEN 1 THEN '销售出库' WHEN 2 THEN '调拨出库' ELSE '' END as type_name, count(1) as count from outbound_order
and date(created_at) >= #{startDate}
and date(created_at) <= #{endDate}
group by outbound_type

select * from outbound_order
where outbound_object_id = #{outboundObjectId}
order by created_at desc

